private boolean isValidHost(String host) {
    if (host == null) {
        return false;
    }
    String address = host.trim();
    if (address.isEmpty()) {
        return false;
    }
    // Remove a scheme if the user typed one, it is added back when the request is built.
    address = address.replaceFirst("(?i)^https?://", "");
    // Drop any path, query or fragment, only the authority has to be validated.
    int endOfAuthority = address.length();
    for (int i = 0; i < address.length(); i++) {
        char c = address.charAt(i);
        if (c == '/' || c == '?' || c == '#') {
            endOfAuthority = i;
            break;
        }
    }
    String authority = address.substring(0, endOfAuthority);
    if (authority.isEmpty()) {
        return false;
    }
    // Split an optional port from the host.
    int portSeparator = authority.lastIndexOf(':');
    if (portSeparator >= 0) {
        String port = authority.substring(portSeparator + 1);
        if (!port.matches("\\d{1,5}")) {
            return false;
        }
        int portNumber = Integer.parseInt(port);
        if (portNumber < 1 || portNumber > 65535) {
            return false;
        }
        authority = authority.substring(0, portSeparator);
    }
    if (authority.isEmpty()) {
        return false;
    }
    // Hostname: labels of alphanumeric characters and hyphens separated by single dots.
